dispatch_case:
// NONE in the diffusion-model factory. AnimateDiff has NO *Runner of its own and is
// NOT constructed via backend_for(SDBackendModule::DIFFUSION)/params_backend_for(...).
// Its blocks live INSIDE the existing UNetModelRunner (fork unet.hpp), which is already
// in fork convention. The "dispatch" is the motion-module wiring in UnetModelBlock.
//
// (A) UnetModelBlock CONSTRUCTOR — after `blocks["out.2"] = ...Conv2d(...)` (fork line ~475), ADD:
if (this->config.enable_animatediff) {
    AnimateDiff::MotionModuleConfig mm_cfg;
    mm_cfg.enable_mid_block = this->config.animatediff_has_mid_block;
    blocks["motion_module"] = std::make_shared<AnimateDiff::AnimateDiffModel>(mm_cfg);
}
//
// (B) UnetModelBlock::forward — the fork already threads `num_video_frames` through
// resblock_forward/attention_layer_forward, so paste upstream's three motion lambdas
// verbatim (they use ctx->ggml_ctx via mm->forward(ctx, h_in, num_video_frames), pure
// fork GGMLRunnerContext convention, NO model_manager). Right after `hs.push_back(h);`
// for input_block 0, ADD:
auto motion_root = config.enable_animatediff && num_video_frames > 1
                       ? std::dynamic_pointer_cast<AnimateDiff::AnimateDiffModel>(blocks["motion_module"])
                       : nullptr;
auto apply_motion_input = [&](int input_block_idx, ggml_tensor* h_in) -> ggml_tensor* {
    if (!motion_root) return h_in;
    int di = (input_block_idx - 1) / 3;
    int mj = (input_block_idx - 1) % 3;
    if (di < 0 || di >= (int)channel_mult.size() || mj < 0 || mj >= num_res_blocks) return h_in;
    auto mm = motion_root->motion("down_blocks." + std::to_string(di) + ".motion_modules." + std::to_string(mj));
    if (!mm) return h_in;
    return mm->forward(ctx, h_in, num_video_frames);
};
auto apply_motion_output = [&](int output_block_idx, ggml_tensor* h_in) -> ggml_tensor* {
    if (!motion_root) return h_in;
    int ui = output_block_idx / 3;
    int mj = output_block_idx % 3;
    if (ui < 0 || ui >= (int)channel_mult.size() || mj < 0 || mj > num_res_blocks) return h_in;
    auto mm = motion_root->motion("up_blocks." + std::to_string(ui) + ".motion_modules." + std::to_string(mj));
    if (!mm) return h_in;
    return mm->forward(ctx, h_in, num_video_frames);
};
auto apply_motion_mid = [&](ggml_tensor* h_in) -> ggml_tensor* {
    if (!motion_root) return h_in;
    auto mm = motion_root->motion("mid_block.motion_modules.0");
    if (!mm) return h_in;
    return mm->forward(ctx, h_in, num_video_frames);
};
// Then insert the calls at the same points as upstream:
